from playwright.sync_api import sync_playwright
import os
with sync_playwright() as p:
 b=p.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox'])
 for width,height in [(1440,1000),(844,390)]:
  page=b.new_page(viewport={'width':width,'height':height},is_mobile=width<1000,has_touch=width<1000);errors=[];page.on('pageerror',lambda e:errors.append(str(e)))
  page.goto(os.environ.get('BLACKLINE_TEST_URL','http://127.0.0.1:8047'),wait_until='networkidle');page.locator('#blackline-continue').click()
  page.evaluate('''()=>{state.simClock.paused=true;state.operations=[];state.overseasCommand.activeId=null;state.overseasCommand.phase='ready';state.cash=5e9;state.team=Array.from({length:36},(_,i)=>['특임팀장','의무부사관','정찰부사관','특전대원','화력지원부사관','저격수'][i%6]).map((role,i)=>({id:101+i,name:'계획대원'+i,country:'대한민국',unit:'가상 부대',rank:'중사',role,skill:90,salary:60000000,birthDate:'1995-01-01',loadout:{primary:'미지급'}}));blacklineReviewArmory();state.ammo=50000;state.med=100;state.missions=[{id:9001,title:'준비 절차 검증',type:'시설 보안',risk:1,mapId:'urban',reward:150000000,contractStatus:'검토 가능',expiresDate:'2031-01-01'}];state.missions.push(...[1,2,3].map(i=>({...state.missions[0],id:9001+i,title:'후속 임무 '+i})));for(let i=0;i<5;i++)blacklineReviewCompany();const op=state.operations[0];if(state.operations.length!==1)throw Error('parallel operation admitted');if(!op||op.workflow.stage!=='approval'||op.preRecon)throw Error('instant recon');go('missions');save();}''')
  assert page.locator('.workflow-step.current').inner_text().endswith('임무 승인 검토')
  before=page.evaluate('JSON.stringify(state.operations[0].workflow)');page.reload(wait_until='networkidle');page.locator('#blackline-continue').click();assert page.evaluate('JSON.stringify(state.operations[0].workflow)')==before
  page.evaluate('''()=>{window.jumpAt=at=>{const days=Math.floor(at/1440)-state.day,d=new Date(state.date+'T00:00:00Z');d.setUTCDate(d.getUTCDate()+days);state.date=d.toISOString().slice(0,10);state.day=Math.floor(at/1440);state.simClock.minutes=at%1440;};window.nextPhase=()=>{jumpAt(state.operations[0].workflow.dueAt);blacklineReviewMissionPlans();};nextPhase();if(state.operations[0].workflow.stage!=='reconPlan')throw Error('recon planning skipped');nextPhase();if(state.operations[0].workflow.stage!=='reconReady')throw Error('recon preparation skipped');window.savedCash=state.cash;state.cash=20000000;state.ammo=0;nextPhase();if(!state.operations[0].workflow.waitingReason||state.operations[0].preRecon)throw Error('stock shortage ignored');state.cash=savedCash;state.ammo=50000;blacklineReviewMissionPlans();const op=state.operations[0];if(op.workflow.stage!=='recon'||!op.preRecon)throw Error('dispatch did not resume');const s=op.preRecon.operation.fieldProgress.tactical;s.units=s.units.filter(u=>u.faction==='blackline');for(let i=0;i<4500&&!s.done;i++)blacklineReconTick();if(!s.done||op.workflow.stage!=='debrief'||op.teamIds.length)throw Error('report/main plan skipped');nextPhase();if(op.workflow.stage!=='mainPlan'||op.teamIds.length)throw Error('main plan delay missing');nextPhase();if(op.teamIds.length!==24||op.taskGroups.length!==3)throw Error('large unit roster missing');if(op.workflow.stage!=='rehearsal'||op.rehearsalAt<=state.day*1440+state.simClock.minutes)throw Error('instant rehearsal');save();go('missions');}''')
  assert page.locator('.workflow-step.current').inner_text().endswith('장비 점검·사전훈련')
  page.screenshot(path='/tmp/blackline-v51-workflow-'+str(width)+'.png')
  page.evaluate('''()=>{const op=state.operations[0];for(let i=0;i<8&&op.status!=='사전 연습 완료';i++){jumpAt(op.rehearsalAt);blacklineRunScheduled();if(op.fieldProgress?.tactical)throw Error('deployed during rehearsal');if(op.status==='추가 연습 필요'&&op.rehearsalAt-state.day*1440-state.simClock.minutes<120)throw Error('instant rehearsal retry');}if(op.status!=='사전 연습 완료')throw Error('rehearsal never finished');blacklineReviewMissionPlans();if(op.workflow.stage!=='deployReady')throw Error('final preparation missing');if(op.deployAt-state.day*1440-state.simClock.minutes<120)throw Error('instant deployment');jumpAt(op.deployAt-1);blacklineRunScheduled();if(op.fieldProgress?.tactical)throw Error('early deployment');jumpAt(op.deployAt);blacklineRunScheduled();blacklineReviewMissionPlans();if(new Set([op.transportPlan.assetId,op.jointTransportOne.assetId,op.jointTransportTwo.assetId]).size!==3)throw Error('convoy missing');if(!op.fieldProgress.tactical.jointOperation)throw Error('joint world missing');if(op.status!=='현장 진행 중'||op.workflow.stage!=='operation'||!op.fieldProgress.tactical)throw Error('main deployment missing');}''')
  assert not errors,errors
  print('PASS',width,height,'approval/planning/preparation/real recon/debrief/main plan/rehearsal/final briefing/main dispatch, stock wait and exact reload')
  page.close()
 b.close()
